/* Files keeps what is still used (round 39). Deleting a file in Files that a product, a website page or anything else of the shop's still shows takes it out of Files and keeps the stored picture: file_details gets hidden_at, the time it left Files. And public.storage_object_referenced, which the daily storage cleanup and Files' delete ask, no longer counts a file_details row (a picture's alt text, or that hidden_at) as a use, so a picture nothing shows any more is still cleaned up. Needs part 214 (file_details) and part 18. No row changes. Until it runs, Files keeps a file in use in its list and says so. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.file_details') IS NOT NULL THEN ALTER TABLE public.file_details ADD COLUMN IF NOT EXISTS hidden_at timestamptz; CREATE INDEX IF NOT EXISTS file_details_hidden_idx ON public.file_details (creator_id) WHERE hidden_at IS NOT NULL; END IF; END $do$;
create or replace function public.storage_object_referenced(p_bucket text, p_name text) returns boolean language plpgsql stable security definer set search_path = public as $$ declare owner_key text := split_part(p_name, '/', 1); pattern text; v_creator uuid; v_user uuid; t record; q text; found boolean := false; skip text[] := array['rate_limit_hits', 'download_events', 'upload_events', 'product_views', 'product_analytics_daily', 'analytics_daily_rollups', 'security_events', 'email_events', 'email_logs', 'email_usage', 'ledger_events', 'seller_ledger', 'signup_attempts', 'site_web_vitals', 'blog_post_views', 'message_push_log', 'flow_execution_log', 'campaign_recipients', 'account_delete_codes', 'oauth_bridge_tokens', 'profile_username_history', 'username_history', 'website_address_history', 'admin_actions', 'admin_moderation_log', 'file_details']; begin if owner_key !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then return true; end if; pattern := '%' || replace(replace(replace(p_name, '\', '\\'), '%', '\%'), '_', '\_') || '%'; select c.id, c.user_id into v_creator, v_user from public.creators c where c.id = owner_key::uuid or c.user_id = owner_key::uuid limit 1; if v_creator is null then v_user := owner_key::uuid; end if; if to_regclass('public.profiles') is not null then execute 'select exists (select 1 from public.profiles x where x.id = $1 and x::text like $2)' into found using v_user, pattern; if found then return true; end if; end if; for t in select c.table_name, c.column_name, (c.data_type = 'uuid') as is_uuid from information_schema.columns c join information_schema.tables tb on tb.table_schema = c.table_schema and tb.table_name = c.table_name where c.table_schema = 'public' and tb.table_type = 'BASE TABLE' and c.column_name in ('creator_id', 'owner_id', 'user_id', 'product_id', 'install_id', 'site_id') and not (c.table_name = any(skip)) order by c.table_name, c.column_name loop q := case when t.column_name = 'creator_id' and v_creator is not null then format('select exists (select 1 from public.%I x where x.creator_id%s = $1%s and x::text like $3)', t.table_name, case when t.is_uuid then '' else '::text' end, case when t.is_uuid then '' else '::text' end) when t.column_name in ('owner_id', 'user_id') and v_user is not null then format('select exists (select 1 from public.%I x where x.%I%s = $2%s and x::text like $3)', t.table_name, t.column_name, case when t.is_uuid then '' else '::text' end, case when t.is_uuid then '' else '::text' end) when t.column_name = 'product_id' and v_creator is not null and to_regclass('public.products') is not null then format('select exists (select 1 from public.%I x join public.products p on p.id%s = x.product_id%s where p.creator_id = $1 and x::text like $3)', t.table_name, case when t.is_uuid then '' else '::text' end, case when t.is_uuid then '' else '::text' end) when t.column_name = 'install_id' and v_creator is not null and to_regclass('public.store_theme_installs') is not null then format('select exists (select 1 from public.%I x join public.store_theme_installs i on i.id%s = x.install_id%s where i.creator_id = $1 and x::text like $3)', t.table_name, case when t.is_uuid then '' else '::text' end, case when t.is_uuid then '' else '::text' end) when t.column_name = 'site_id' and v_creator is not null and to_regclass('public.sites') is not null then format('select exists (select 1 from public.%I x join public.sites s on s.id%s = x.site_id%s where s.creator_id = $1 and x::text like $3)', t.table_name, case when t.is_uuid then '' else '::text' end, case when t.is_uuid then '' else '::text' end) else null end; continue when q is null; begin execute q into found using v_creator, v_user, pattern; exception when others then found := true; end; if found then return true; end if; end loop; return false; end; $$;
revoke all on function public.storage_object_referenced(text, text) from public, anon, authenticated;
grant execute on function public.storage_object_referenced(text, text) to service_role;
notify pgrst, 'reload schema';
